#define R2D(a) mat2(cos(a+vec4(0,11,33,0)))

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    float i,j,d=.1,e=0.;
    vec3 p;
    fragColor=vec4(0.);

    for(i=0.;i++<64.&&d>1e-4;){
        p=vec3((fragCoord.xy-.5*iResolution.xy)/iResolution.y,e);
        p.xy*=R2D(iTime*.5)+cos(iTime*.5);

        for(j=0.;j++<16.;)
            p.yz*=R2D(22.22),
            p=abs(abs(p*reflect(p-.02,vec3(-1))))-.325,
            p.x<p.y?p.yz+=p.zx:p.xz+=p.yz,
            d-=dot(p,p)/1e4;
        e+=d;

    }fragColor += vec4(p,1)*3./i;
}
